document.getElementById('year').textContent=new Date().getFullYear();
document.querySelectorAll('[data-service]').forEach(button=>button.addEventListener('click',()=>{document.getElementById('service').value=button.dataset.service;document.getElementById('orcamento').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}));
document.querySelectorAll('[data-color]').forEach(button=>button.addEventListener('click',()=>{document.getElementById('demo').className='color-demo '+button.dataset.color;document.querySelectorAll('[data-color]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});}));
document.getElementById('quote').addEventListener('submit',event=>{event.preventDefault();const service=document.getElementById('service').value;const details=document.getElementById('details').value.trim();const message='Olá, PrintZ+! Vim pelo site e gostaria de um orçamento.\n\nServiço: '+service+(document.getElementById('quantity').value?'\nQuantidade aproximada: '+document.getElementById('quantity').value:'')+(document.getElementById('deadline').value?'\nData desejada: '+document.getElementById('deadline').value.split('-').reverse().join('/'):'')+(details?'\nMinha ideia: '+details:'');window.open('https://wa.me/5535997707674?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');});
const menuToggle=document.querySelector('.menu-toggle');const mainNav=document.getElementById('main-nav');
menuToggle.addEventListener('click',()=>{const open=menuToggle.getAttribute('aria-expanded')!=='true';menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');mainNav.classList.toggle('open',open)});
mainNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mainNav.classList.remove('open');menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Abrir menu')}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(other=>{other.classList.toggle('active',other===b);other.setAttribute('aria-pressed',String(other===b))});document.querySelectorAll('.project').forEach(p=>p.hidden=b.dataset.filter!=='all'&&p.dataset.category!==b.dataset.filter)}));
const projectDialog=document.getElementById('project-dialog');let projectOrigin=null;let projectService='';
document.querySelectorAll('.project').forEach(p=>p.addEventListener('click',()=>{projectOrigin=p;projectService=p.dataset.projectService;document.getElementById('project-image').src=p.querySelector('img').getAttribute('src');document.getElementById('project-image').alt=p.dataset.desc;document.getElementById('project-title').textContent=p.dataset.title;document.getElementById('project-desc').textContent=p.dataset.desc;projectDialog.showModal();document.body.style.overflow='hidden'}));
function closeProject(){projectDialog.close()}
projectDialog.querySelector('.dialog-close').addEventListener('click',closeProject);projectDialog.addEventListener('click',e=>{if(e.target===projectDialog){const r=projectDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeProject()}});projectDialog.addEventListener('close',()=>{document.body.style.overflow='';if(projectOrigin)projectOrigin.focus({preventScroll:true})});
document.getElementById('project-request').addEventListener('click',()=>{closeProject();document.getElementById('service').value=projectService;document.getElementById('details').value='Gostei da referência: '+document.getElementById('project-title').textContent+'. Gostaria de conversar sobre um projeto parecido.';document.getElementById('orcamento').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})});
let scrollTick=false;addEventListener('scroll',()=>{if(!scrollTick){requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress').style.width=(max>0?scrollY/max*100:0)+'%';scrollTick=false});scrollTick=true}},{passive:true});
const ideas={marca:{number:'01',title:'Sua marca merece espaço.',text:'Combine cartões, adesivos e uma fachada com personalidade para criar uma presença que as pessoas reconheçam.',cta:'Vamos criar para minha marca',service:'Fachadas'},festa:{number:'02',title:'Um cenário para boas memórias.',text:'Displays personalizados e backdrops ajudam a dar o tom da sua celebração. Conte o tema, a data e o espaço que você tem em mente.',cta:'Vamos planejar minha festa',service:'Displays para festa'},presente:{number:'03',title:'O melhor detalhe é ser pessoal.',text:'Uma caneca, um copo ou uma lembrança com a sua ideia. Transforme nomes, frases e referências em um presente com significado.',cta:'Vamos personalizar meu presente',service:'Canecas e copos personalizados'}};let selectedIdea='marca';
document.querySelectorAll('[data-idea]').forEach(b=>b.addEventListener('click',()=>{selectedIdea=b.dataset.idea;const idea=ideas[selectedIdea];document.querySelector('.idea-lab').dataset.mode=selectedIdea;document.getElementById('idea-number').textContent=idea.number;document.getElementById('idea-title').textContent=idea.title;document.getElementById('idea-text').textContent=idea.text;document.getElementById('idea-cta').textContent=idea.cta+' ↗';document.querySelectorAll('[data-idea]').forEach(other=>{other.classList.toggle('active',other===b);other.setAttribute('aria-pressed',String(other===b))})}));
document.getElementById('idea-cta').addEventListener('click',()=>{document.getElementById('service').value=ideas[selectedIdea].service;document.getElementById('orcamento').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})});
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('entered');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.section-top,.about-art,.about-copy,.service,.extras,.more-services,.project,.play-section>div,.steps>div,.faq>div,.quote-section>div,.quote-section form,.contact>div,.idea-lab>h2,.idea-result').forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--delay',(el.classList.contains('project')?i%3*70:0)+'ms');observer.observe(el)});document.body.classList.add('motion-ready')}
// Begin only after the browser has rendered a visible page.
let introTimer;let introFrame=0;
function playPrintIntro(){
 if(document.visibilityState==='hidden')return;
 clearTimeout(introTimer);cancelAnimationFrame(introFrame);
 document.documentElement.classList.remove('intro-enabled');
 introFrame=requestAnimationFrame(()=>{introFrame=requestAnimationFrame(()=>{
 document.documentElement.classList.add('intro-enabled');
 introTimer=setTimeout(()=>document.documentElement.classList.remove('intro-enabled'),2700);
 });});
}
function schedulePrintIntro(){if(document.visibilityState==='hidden'){document.addEventListener('visibilitychange',function visible(){if(document.visibilityState==='visible'){document.removeEventListener('visibilitychange',visible);playPrintIntro();}});}else playPrintIntro();}
if(document.readyState==='complete')schedulePrintIntro();else window.addEventListener('load',schedulePrintIntro,{once:true});
document.querySelector('.replay-intro').addEventListener('click',playPrintIntro);
window.addEventListener('pageshow',event=>{if(event.persisted)schedulePrintIntro()});
// Update only while the print story is on screen; scrolling remains native.
(()=>{const story=document.querySelector('.print-journey');if(!story)return;const chapters=[...story.querySelectorAll('[data-j-step]')],labels=['01 / O PRIMEIRO TRAÇO','02 / CAMADAS DE COR','03 / IMPRESSÃO E ACABAMENTO','04 / PRONTA PARA APARECER'];const controls=[...story.querySelectorAll('[data-j-go]')];controls.forEach(button=>button.addEventListener('click',()=>{const chapter=chapters[Number(button.dataset.jGo)],visual=story.querySelector('.journey-visual').getBoundingClientRect();const target=innerWidth<=720?Math.min(innerHeight-100,visual.height+132):innerHeight*.55;const r=chapter.getBoundingClientRect();window.scrollTo({top:scrollY+r.top+r.height/2-target,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}));let frame=0,visible=true;function update(){frame=0;if(!visible)return;const visual=story.querySelector('.journey-visual').getBoundingClientRect();const target=innerWidth<=720?Math.min(innerHeight-100,visual.bottom+120):innerHeight*.55;let current=0,distance=Infinity;chapters.forEach((chapter,i)=>{const r=chapter.getBoundingClientRect(),d=Math.abs(r.top+r.height/2-target);if(d<distance){distance=d;current=i}});if(story.dataset.stage!==String(current)){story.dataset.stage=current;controls.forEach((button,i)=>button.setAttribute('aria-pressed',String(i===current)));document.getElementById('journey-stage-label').textContent=labels[current];chapters.forEach((chapter,i)=>chapter.classList.toggle('is-current',i===current))}}function schedule(){if(visible&&!frame)frame=requestAnimationFrame(update)}if('IntersectionObserver'in window)new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)schedule()},{rootMargin:'100px'}).observe(story);addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});schedule()})();
